# Both presentations consume exactly the same canonical report object.
def render_md(r):
    out=[f'# {r["title"]}',f'问题：{r["question"]}',f'研究完成截点：{r["as_of"]}；证据截止日：2026-10-31。最新已核对披露：2026-10-28 / FY27 Q1（截至2026-09-30）。状态：部分完成（回报与治理资料有明确缺口）。',r['answer']+' ['+']['.join(r['answer_claim_ids'])+']','下一条会改变判断的观察：'+r['watch'][0]['signal']+'。 [C24]']
    for f in r['findings']: out += ['## '+f['title'],f['text']+' ['+']['.join(f['claim_ids'])+']']
    out+=['数字口径：1十亿美元=10亿美元；FY26为2025-07至2026-06，FY27为2026-07至2027-06；FY27 H2为2027-01至06。各季实际取披露四舍五入数；现金PP&E + 融资租赁不能机械等于capex。经营租赁不在该capex数中；它仍有资源/支付义务。 [C5][C7][C8]']
    for t in r['tables']:
        table_lines=['| '+' | '.join(t['columns'])+' |','| '+' | '.join(['---']*len(t['columns']))+' |']
        table_lines += ['| '+' | '.join(str(c).replace('|','／') for c in row)+' |' for row in t['rows']]
        out+=['## '+t['title'],'\n'.join(table_lines)]
    out += ['## 已宣布、已上线与回报的边界','FY26 Q1的Fairwater Wisconsin两GW是宣布中的目标，原话称次年上线；本轮不把它当作完成。据管理层披露新增数据中心/GW支持部分产能形成，但具体新增AI批次可售GPU容量/利用率未核实。 [C9][C10]','FY26四季现金PP&E与融资租赁之和并非精确年度capex：收货/付款时点有差异。FY27 Q1现金PP&E同比+200亿美元、约+103.1%，报告capex同比约+29.5%则跨越租赁分类变化，不能当同口径扩张率。具体公式、输入和不计算的ROI在calculations.json。 [C5][C26]']
    out+=['## 有依据的替代解释']
    for a in r['alternatives']: out += ['**'+a['title']+'**',a['text']+' ['+']['.join(a['claim_ids'])+']']
    out+=['## 下一验证']
    for w in r['watch']: out += ['- **'+w['signal']+'**：'+w['meaning']+' ['+']['.join(w['claim_ids'])+']']
    out+=['## 集中说明的局限']+['- '+g for g in r['gaps']]
    out+=['## 一手来源与审计入口']
    out += [f'- [{s["id"]} · {s["title"]}]({s["url"]})，{s["published_at"]}。' for s in r['sources']]
    out += ['原话全文段落、日期、URL、获取时间和本地行号见sources.json；claims.json绑定结论与原话，calculations.json保存公式。Markdown与HTML由同一report.json生成。研究建议，不是买卖建议。']
    return '\n\n'.join(out)+'\n'
def render_html(r):
    e=html.escape
    blocks=[f'<h1>{e(r["title"])}</h1>',f'<p>{e(r["question"])}</p>',f'<p>截点：{e(r["as_of"])}；最新披露：2026-10-28 / FY27 Q1；状态：部分完成。</p>',f'<p><strong>{e(r["answer"])}</strong> [{e("][".join(r["answer_claim_ids"]))}]</p>',f'<p>下一验证：{e(r["watch"][0]["signal"])} [C24]</p>']
    for f in r['findings']:blocks += [f'<h2>{e(f["title"])}</h2><p>{e(f["text"])} [{e("][".join(f["claim_ids"]))}]</p>']
    blocks+=['<p>金额表单位：十亿美元；FY26截至2026年6月，FY27截至2027年6月。现金PP&E、融资租赁与报告capex不同；经营租赁移出capex仍有支付义务。 [C5][C7][C8]</p>']
    for t in r['tables']:
        blocks += [f'<h2>{e(t["title"])}</h2><div class="scroll" tabindex="0"><table><thead><tr>'+''.join(f'<th scope="col">{e(c)}</th>' for c in t['columns'])+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{e(str(c))}</td>' for c in row)+'</tr>' for row in t['rows'])+'</tbody></table></div>']
    blocks+=['<h2>已宣布、已上线与回报的边界</h2><p>Fairwater Wisconsin的2GW仍是宣布中的目标，不能计为已完成；据管理层披露的数据中心/GW不等于具体新增AI批次可售GPU容量，后者及利用率未核实。 [C9][C10]</p><p>FY27 Q1现金PP&E同比+200亿美元、约+103.1%；报告capex同比约+29.5%跨越分类变化，不能当同口径扩张率。 [C5][C26]</p>','<h2>有依据的替代解释</h2>']
    for a in r['alternatives']:blocks += [f'<h3>{e(a["title"])}</h3><p>{e(a["text"])} [{e("][".join(a["claim_ids"]))}]</p>']
    blocks+=['<h2>下一验证</h2><ul>']+[f'<li><strong>{e(w["signal"])}</strong>：{e(w["meaning"])} [{e("][".join(w["claim_ids"]))}]</li>' for w in r['watch']]+['</ul><h2>集中说明的局限</h2><ul>']+[f'<li>{e(g)}</li>' for g in r['gaps']]+['</ul><h2>一手来源</h2><ul>']+[f'<li><a href="{e(s["url"])}">{e(s["id"]+" · "+s["title"])}</a>，{e(s["published_at"])}</li>' for s in r['sources']]+['</ul><p>原话与审计入口：sources.json / claims.json / calculations.json。研究建议，不是买卖建议。</p>']
    return '<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+e(r['title'])+'</title><style>body{max-width:1100px;margin:40px auto;padding:0 24px;font:17px/1.75 system-ui;color:#17202a;background:#fff}h1{font-size:28px}h2{font-size:22px;margin-top:2em}h3{font-size:18px}table{border-collapse:collapse;width:100%;font-size:14px}th,td{padding:10px;border:1px solid #bbb;text-align:left;vertical-align:top}a{color:#1457a8}.scroll{overflow:auto} @media print{body{margin:0;max-width:none;font-size:11pt}.scroll{overflow:visible}table{font-size:9pt}tr{break-inside:avoid}}</style><main>'+''.join(blocks)+'</main></html>\n'
